import { EmptyState, type EmptyStateActionDetail } from '@absoluteui/components/empty-state';

const host = document.createElement('div');
document.body.append(host);
EmptyState.create(host, {
  title: 'No employees match your filters',
  description: 'Try a different name or clear the filters.',
  icon: 'search',
  live: true,
  primaryAction: { label: 'Clear filters' },
});
host.addEventListener('aui-action', (event) => {
  if ((event as CustomEvent<EmptyStateActionDetail>).detail.action === 'primary') host.dataset.cleared = 'true';
});

import { EmptyState } from '@absoluteui/components/empty-state';

